@import 'c/rlySharedStyles';

.rr-ru { position: relative; background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); padding: 12px 14px 16px; display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.rr-ru-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-weak { color: #5c5c5c; }
.rr-mono { font-family: Menlo, Consolas, monospace; font-size: 12px; }
.rr-break { overflow-wrap: anywhere; }
.rr-hint { font-size: 11.5px; color: #5c5c5c; margin: 2px 0 0; }
.rr-label { font-size: 12px; color: #5c5c5c; margin: 0 0 4px; }
.rr-ru-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px 14px; }
.rr-ru-field { min-width: 0; }
.rr-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 6px 14px; margin: 0; }
.rr-facts dt { font-size: 11.5px; color: #5c5c5c; }
.rr-facts dd { margin: 0; font-size: 12.5px; overflow-wrap: anywhere; }
.rr-steps { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.rr-step-wrap { display: inline-flex; align-items: center; gap: 6px; }
.rr-arrow { color: #b0b0b0; }
.rr-chip { display: inline-flex; align-items: center; gap: 6px; border: 1px solid #c9c9c9; border-radius: 16px; padding: 4px 11px 4px 5px; background: #fff; font-size: 12.5px; color: #181818; cursor: pointer; }
.rr-chip:disabled { cursor: default; }
.rr-n { width: 20px; height: 20px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; background: #f3f3f3; color: #5c5c5c; }
.rr-chip.rr-sel { border-color: #0176d3; background: #eef4ff; color: #014486; box-shadow: inset 0 0 0 1px #0176d3; }
.rr-chip.rr-sel .rr-n { background: #0176d3; color: #fff; }
.rr-chip.rr-off { color: #8a8a8a; border-color: #e5e5e5; background: #fafafa; }
.rr-chip.rr-off .rr-n { background: #f0f0f0; color: #8a8a8a; }
.rr-chip.rr-done .rr-n { background: #2e844a; color: #fff; }
.rr-chip.rr-fail .rr-n { background: #ba0517; color: #fff; }
.rr-chip.rr-run .rr-n { background: #eef4ff; color: #0176d3; border: 2px solid #0176d3; }
.rr-st { font-size: 11px; font-weight: 600; }
.rr-chip.rr-done .rr-st { color: #2e844a; }
.rr-chip.rr-fail .rr-st { color: #ba0517; }
.rr-chip.rr-run .rr-st { color: #0176d3; }
.rr-what { font-size: 12.5px; background: #fafaf9; border: 1px solid #e5e5e5; border-radius: 4px; padding: 8px 10px; }
.rr-tbl { border: 1px solid #e5e5e5; border-radius: 4px; overflow-x: auto; }
.rr-tr { display: grid; grid-template-columns: minmax(120px, 1.15fr) minmax(80px, .8fr) minmax(150px, 1.25fr) minmax(80px, .7fr) minmax(60px, .55fr) minmax(60px, .6fr); gap: 8px; align-items: center; padding: 7px 10px; border-bottom: 1px solid #f1f1f1; font-size: 12px; min-width: 600px; }
.rr-tr:last-child { border-bottom: 0; }
.rr-th { background: #fafaf9; color: #5c5c5c; font-weight: 600; font-size: 11.5px; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-fails { margin: 0; padding: 0; list-style: none; border: 1px solid #f5c9c2; border-radius: 4px; background: #fffafa; max-height: 260px; overflow-y: auto; }
.rr-fails li { padding: 6px 10px; border-bottom: 1px solid #fbe3df; font-size: 12px; }
.rr-fails li:last-child { border-bottom: 0; }
.rr-acts { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; align-items: center; }
.rr-tick { position: absolute; width: 1px; height: 1px; opacity: 0.01; pointer-events: none; animation: rr-tick 30s linear; }
.rr-tick-30 { animation-duration: 30s; }
@keyframes rr-tick { from { transform: translateX(0); } to { transform: translateX(1px); } }
